import 'package:dio/dio.dart';

import '../../../core/errors/app_exception.dart';
import '../../../core/money/rial.dart';
import '../domain/market_quote.dart';
import '../domain/market_symbols.dart';
import 'price_math.dart';
import 'price_provider.dart';

/// Prices fiat currencies, gold coins and gold bullion from Bonbast.
///
/// Bonbast protects its rate feed with a short-lived token that is generated by
/// inline JavaScript on the home page and posted to `/json`. Instead of driving
/// a headless browser, this provider performs the same two requests a browser
/// would: fetch the page, lift the token (and session cookie) out of it, then
/// post the token and parse the JSON rates. Prices in that JSON are in Toman,
/// so every value is multiplied by ten into integer Rial with exact rounding.
final class BonbastPriceProvider implements PriceProvider {
  const BonbastPriceProvider();

  /// Stable source name used in quotes and merge priority.
  static const String sourceName = 'Bonbast';

  /// Home page that embeds the rate token.
  static const String pageUrl = 'https://bonbast.com/';

  /// Endpoint that returns the rate JSON for a valid token.
  static const String jsonUrl = 'https://bonbast.com/json';

  /// Browser-like user agent: Bonbast blocks default Dart/Flutter agents.
  static const String userAgent =
      'Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 '
      '(KHTML, like Gecko) Chrome/139.0.7258.160 Mobile Safari/537.36';

  /// Fiat codes whose Toman quote covers more than one unit.
  static const Map<String, int> _unitsPerQuote = <String, int>{
    'AMD': 10,
    'JPY': 10,
    'IQD': 100,
  };

  /// Canonical gold-coin symbol to the Bonbast key prefix; the buy price of
  /// each coin lives at `<key>2`.
  static const Map<String, String> _goldCoinKeys = <String, String>{
    'AZADI': 'azadi1',
    'EMAMI': 'emami1',
    'AZADI_HALF': 'azadi1_2',
    'AZADI_QUARTER': 'azadi1_4',
    'GERAMI': 'azadi1g',
  };

  /// Grams in one troy ounce, used to derive the silver price.

  static const Map<String, int> _months = <String, int>{
    'january': 1,
    'february': 2,
    'march': 3,
    'april': 4,
    'may': 5,
    'june': 6,
    'july': 7,
    'august': 8,
    'september': 9,
    'october': 10,
    'november': 11,
    'december': 12,
  };

  static final RegExp _tokenPattern = RegExp(
    "param\\s*:\\s*['\"]([^'\"]+)['\"]",
  );
  static final RegExp _timestampPattern = RegExp(
    r'^([A-Za-z]+) (\d{1,2}), (\d{4}) (\d{2}):(\d{2})$',
  );

  @override
  String get name => sourceName;

  @override
  Future<List<MarketQuote>> fetch(Dio dio) async {
    final page = await _getPage(dio);
    final token = extractToken(page.data ?? '');
    final cookie = extractSessionCookie(page.headers['set-cookie']);
    final response = await _postToken(dio, token: token, cookie: cookie);
    return parseBody(response.data ?? '', fetchedAt: DateTime.now().toUtc());
  }

  /// Extracts the `param` token from Bonbast's inline JavaScript.
  ///
  /// Throws a user-facing [ValidationException] when the page does not contain
  /// the token (for example when Bonbast serves a challenge page).
  static String extractToken(String html) {
    final match = _tokenPattern.firstMatch(html);
    final token = match?.group(1)?.trim();
    if (token == null || token.isEmpty) {
      throw const ValidationException(
        'دریافت نرخ از بون‌بست انجام نشد. دوباره تلاش کن.',
        debugDetail: 'bonbast token not found in home page',
      );
    }
    return token;
  }

  /// Returns the `st_bb` cookie from the home page response.
  ///
  /// Bonbast hands out `st_bb=0` on a normal page load; when the header is
  /// missing (redirect, cached response) the known-good value is sent instead so
  /// the JSON request still has the session marker the endpoint expects.
  static String extractSessionCookie(List<String>? setCookieHeaders) {
    if (setCookieHeaders != null) {
      for (final header in setCookieHeaders) {
        for (final part in header.split(';')) {
          final pair = part.trim();
          if (pair.startsWith('st_bb=') && pair.length > 'st_bb='.length) {
            return pair;
          }
        }
      }
    }
    return 'st_bb=0';
  }

  /// Parses a raw Bonbast JSON body.
  static List<MarketQuote> parseBody(String body, {DateTime? fetchedAt}) {
    final json = decodeJsonObject(body);
    if (json == null) {
      throw const ValidationException(
        'پاسخ نرخ بون‌بست معتبر نیست.',
        debugDetail: 'bonbast response is not a json object',
      );
    }
    return parseJson(json, fetchedAt: fetchedAt);
  }

  /// Parses the already-decoded Bonbast rate JSON into canonical quotes.
  ///
  /// Missing or malformed individual numbers are skipped; a payload without any
  /// usable quote throws instead, so the service records a failed source.
  static List<MarketQuote> parseJson(
    Map<String, Object?> json, {
    DateTime? fetchedAt,
  }) {
    final updatedAt =
        parseLastModified(json['last_modified']) ??
        fetchedAt ??
        DateTime.now().toUtc();
    final quotes = <MarketQuote>[];

    for (final symbol in fiatSymbols) {
      final prefix = symbol.toLowerCase();
      final units = _unitsPerQuote[symbol] ?? 1;
      final sell = tomanToRial(json['${prefix}1'], unitsPerQuote: units);
      final buy = tomanToRial(json['${prefix}2'], unitsPerQuote: units);
      final price = sell ?? buy;
      if (price == null) continue;
      quotes.add(
        MarketQuote(
          symbol: symbol,
          kind: MarketAssetKind.fiat,
          priceRial: price,
          sellRial: sell,
          buyRial: buy,
          source: sourceName,
          updatedAt: updatedAt,
        ),
      );
    }

    for (final entry in _goldCoinKeys.entries) {
      final sellKey = entry.value;
      final sell = tomanToRial(json[sellKey]);
      final buy = tomanToRial(json['${sellKey}2']);
      final price = sell ?? buy;
      if (price == null) continue;
      quotes.add(
        MarketQuote(
          symbol: entry.key,
          kind: MarketAssetKind.goldCoin,
          priceRial: price,
          sellRial: sell,
          buyRial: buy,
          source: sourceName,
          updatedAt: updatedAt,
        ),
      );
    }

    final gram = tomanToRial(json['gol18']);
    if (gram != null) {
      quotes.add(
        MarketQuote(
          symbol: goldGramSymbol,
          kind: MarketAssetKind.goldGram,
          priceRial: gram,
          source: sourceName,
          updatedAt: updatedAt,
        ),
      );
    }
    final mithqal = tomanToRial(json['mithqal']);
    if (mithqal != null) {
      quotes.add(
        MarketQuote(
          symbol: mithqalSymbol,
          kind: MarketAssetKind.goldGram,
          priceRial: mithqal,
          source: sourceName,
          updatedAt: updatedAt,
        ),
      );
    }

    final usdToman = _tomanInteger(json['usd1']) ?? _tomanInteger(json['usd2']);
    final bitcoin = _deriveBitcoin(json['bitcoin'], usdToman);
    if (bitcoin != null) {
      quotes.add(
        MarketQuote(
          symbol: 'BTC',
          kind: MarketAssetKind.crypto,
          priceRial: bitcoin,
          source: sourceName,
          updatedAt: updatedAt,
        ),
      );
    }

    if (quotes.isEmpty) {
      throw const ValidationException(
        'پاسخ نرخ بون‌بست نرخی نداشت.',
        debugDetail: 'bonbast payload contained no usable price',
      );
    }
    return quotes;
  }

  /// Parses Bonbast's `last_modified` field (`November 27, 2026 08:51`).
  ///
  /// The field carries UTC wall-clock time without an explicit zone: the token
  /// embedded next to it in the home page matches the HTTP `Date` header of the
  /// same response (both GMT), so no offset is applied. Returns `null` when the
  /// format is not the expected one, letting the caller fall back to the fetch
  /// time.
  static DateTime? parseLastModified(Object? value) {
    if (value is! String) return null;
    final match = _timestampPattern.firstMatch(value.trim());
    if (match == null) return null;
    final month = _months[match.group(1)!.toLowerCase()];
    final day = int.tryParse(match.group(2)!);
    final year = int.tryParse(match.group(3)!);
    final hour = int.tryParse(match.group(4)!);
    final minute = int.tryParse(match.group(5)!);
    if (month == null ||
        day == null ||
        year == null ||
        hour == null ||
        minute == null ||
        day < 1 ||
        day > 31 ||
        year < 2000 ||
        year > 2200 ||
        hour > 23 ||
        minute > 59) {
      return null;
    }
    return DateTime.utc(year, month, day, hour, minute);
  }

  static int? _tomanInteger(Object? value) {
    final decimal = MarketDecimal.tryParse(value);
    return decimal?.toIntHalfUp(BigInt.one, BigInt.one);
  }

  /// Derives the Rial price of one bitcoin from Bonbast's USD `bitcoin` field
  /// and the USD/Toman rate.
  static Rial? _deriveBitcoin(Object? bitcoinValue, int? usdToman) {
    if (usdToman == null || usdToman <= 0) return null;
    final bitcoin = MarketDecimal.tryParse(bitcoinValue);
    if (bitcoin == null) return null;
    final rial = bitcoin.toIntHalfUp(
      BigInt.from(usdToman) * BigInt.from(10),
      BigInt.one,
    );
    return rial == null ? null : Rial(rial);
  }

  Future<Response<String>> _getPage(Dio dio) async {
    try {
      return await dio.get<String>(
        pageUrl,
        options: Options(
          responseType: ResponseType.plain,
          headers: <String, String>{
            'User-Agent': userAgent,
            'Accept':
                'text/html,application/xhtml+xml,application/xml;q=0.9,'
                'image/avif,image/webp,*/*;q=0.8',
            'Accept-Language': 'en-US,en;q=0.9',
            'Cache-Control': 'no-cache',
            'Pragma': 'no-cache',
          },
        ),
      );
    } on DioException catch (error) {
      throw ValidationException(
        'اتصال به بون‌بست برقرار نشد. دوباره تلاش کن.',
        debugDetail: _describe(error),
      );
    }
  }

  Future<Response<String>> _postToken(
    Dio dio, {
    required String token,
    required String cookie,
  }) async {
    try {
      return await dio.post<String>(
        jsonUrl,
        data: <String, String>{'param': token},
        options: Options(
          contentType: Headers.formUrlEncodedContentType,
          responseType: ResponseType.plain,
          headers: <String, String>{
            'User-Agent': userAgent,
            'Accept': 'application/json, text/javascript, */*; q=0.01',
            'Accept-Language': 'en-US,en;q=0.9',
            'X-Requested-With': 'XMLHttpRequest',
            'Referer': pageUrl,
            'Origin': 'https://bonbast.com',
            'Cookie': cookie,
          },
        ),
      );
    } on DioException catch (error) {
      throw ValidationException(
        'دریافت نرخ از بون‌بست انجام نشد. دوباره تلاش کن.',
        debugDetail: _describe(error),
      );
    }
  }

  static String _describe(DioException error) {
    final status = error.response?.statusCode;
    final parts = <String>[
      error.requestOptions.uri.toString(),
      error.type.name,
      if (status != null) 'HTTP $status',
      if (error.message != null) error.message!,
    ];
    return parts.join(' | ');
  }
}
